export type DiagnosticBodyEnd = "receiving" | "complete" | "protocolEnd" | "interrupted";

export type DiagnosticDetail = { kind: "httpRequest"; method: string; url: string; headers: DiagnosticHeader[]; headersTruncated: boolean; body: DiagnosticText } | { kind: "httpResponse"; status: number; headers: DiagnosticHeader[]; headersTruncated: boolean; body: DiagnosticText } | { kind: "transportError"; body: DiagnosticText } | { kind: "command"; command: DiagnosticText; stdout: DiagnosticText; stderr: DiagnosticText; stdoutCaptured: boolean; exitStatus: number | null; exitSignal: string | null };

export type DiagnosticHeader = {
	name: string,
	value: string,
	encoding: string,
	redacted: boolean,
};

export type DiagnosticOperation = {
	id: string,
	source: string,
	action: string,
	target: string,
	correlationId: string | null,
	trace: DiagnosticText | null,
	progress: DiagnosticProgress | null,
	discardedDetails: number,
	metadataTruncated: boolean,
	redacted: boolean,
	startedAt: number,
	elapsedMs: number,
	status: DiagnosticStatus,
	phase: DiagnosticPhase,
	details: DiagnosticDetail[],
	error: AppError | null,
};

export type DiagnosticPhase = "preparing" | "sending" | "receiving" | "executing" | "finished";

export type DiagnosticProgress = {
	phase: string,
	completed: number,
	total: number | null,
};

export type DiagnosticSnapshot = {
	cursor: number,
	discarded: number,
	operations: DiagnosticOperation[] | null,
};

export type DiagnosticStatus = "running" | "passed" | "unverified" | "failed" | "interrupted";

export type DiagnosticText = {
	text: string,
	encoding: string,
	receivedBytes: number,
	capturedBytes: number,
	redacted: boolean,
	truncated: boolean,
	end: DiagnosticBodyEnd,
};

